import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353;

    static long binaryExponentiation(long base, long exp) {
        long res = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % MOD;
            }
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    static long computeModInverse(long x) {
        return binaryExponentiation(x, MOD - 2);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] tokens = br.readLine().split(" ");
        long n = Long.parseLong(tokens[0]);
        long m = Long.parseLong(tokens[1]);
        long l = Long.parseLong(tokens[2]);
        long r = Long.parseLong(tokens[3]);

        PrintWriter pw = new PrintWriter(System.out);
        if (l == r) {
            pw.println(1);
            pw.flush();
            return;
        }

        long oddCount = ((r + 1) / 2) - (l / 2);
        long evenCount = (r / 2) - ((l - 1) / 2);
        long totalCells = n * m;

        long answer;
        if (totalCells % 2 == 1) {
            answer = binaryExponentiation(oddCount + evenCount, totalCells);
        } else {
            long sum = (binaryExponentiation(oddCount + evenCount, totalCells) + binaryExponentiation(oddCount - evenCount, totalCells)) % MOD;
            answer = (sum * computeModInverse(2)) % MOD;
        }
        pw.println(answer);
        pw.flush();
    }
}
