#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long binaryExponentiation(long long base, long long exp) {
    long long res = 1LL;
    while (exp > 0) {
        if (exp & 1) {
            res = (res * base) % MOD;
        }
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

long long computeModInverse(long long x) {
    return binaryExponentiation(x, MOD - 2);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, l, r;
    cin >> n >> m >> l >> r;

    if (l == r) {
        cout << 1 << "\n";
        return 0;
    }

    long long oddCount = ((r + 1) / 2) - (l / 2);
    long long evenCount = (r / 2) - ((l - 1) / 2);
    long long totalCells = n * m;

    long long answer;
    if (totalCells % 2 == 1) {
        answer = binaryExponentiation(oddCount + evenCount, totalCells);
    } else {
        long long sum = (binaryExponentiation(oddCount + evenCount, totalCells) + binaryExponentiation(oddCount - evenCount, totalCells)) % MOD;
        answer = (sum * computeModInverse(2)) % MOD;
    }
    cout << answer << "\n";

    return 0;
}
